WITH flattened AS (SELECT id, plan, effective_from, currency, EXPLODE_OUTER(tier_limits) AS val FROM price_tiers), with_windows AS (SELECT id, plan, effective_from, SUM(val) OVER (PARTITION BY plan) AS plan_sum_val, DENSE_RANK() OVER (ORDER BY val DESC NULLS FIRST) AS val_dense_rank FROM flattened), with_windows_price_tiers AS (SELECT id, plan, effective_from, val_dense_rank, MAX(val_dense_rank) OVER w_part AS plan_max_val_dense_rank, DENSE_RANK() OVER w_grp AS plan_sum_val_dense_rank, AVG(val_dense_rank) OVER w_part AS plan_avg_val_dense_rank, DENSE_RANK() OVER (PARTITION BY plan ORDER BY val_dense_rank) AS val_dense_rank_dense_rank FROM with_windows WINDOW w_part AS (PARTITION BY plan), w_grp AS (PARTITION BY plan ORDER BY plan_sum_val NULLS FIRST)), scored AS (SELECT *, ROUND(plan_max_val_dense_rank / SUM(plan_max_val_dense_rank) OVER (PARTITION BY plan), 4) AS plan_max_val_dense_rank_share, DENSE_RANK() OVER (PARTITION BY plan ORDER BY plan_max_val_dense_rank DESC) AS plan_max_val_dense_rank_dense_rank, ROUND(plan_max_val_dense_rank / SUM(plan_max_val_dense_rank) OVER (PARTITION BY plan), 4) AS plan_max_val_dense_rank_share_2, COUNT(val_dense_rank) OVER (PARTITION BY plan) AS plan_count_val_dense_rank FROM with_windows_price_tiers WHERE plan_sum_val_dense_rank <= 3), valid AS (SELECT *, GREATEST(plan_max_val_dense_rank_share, plan_count_val_dense_rank) AS greatest_plan_max_val_dense_rank_share_plan_count_val_dense_rank FROM scored WHERE effective_from > TO_DATE('2024-05-04') AND plan_sum_val_dense_rank <= 8), filtered AS (SELECT *, CAST(plan_sum_val_dense_rank AS STRING) AS plan_sum_val_dense_rank_num FROM valid WHERE effective_from > TO_DATE('2024-03-20')), valid_price_tiers AS (SELECT *, LEAST(plan_count_val_dense_rank, val_dense_rank_dense_rank) AS least_plan_count_val_dense_rank_val_dense_rank_dense_rank FROM filtered WHERE effective_from >= DATE '2024-06-13' AND plan_sum_val_dense_rank BETWEEN 6 AND 8) SELECT DATE_TRUNC('MONTH', effective_from) AS activity_month, ROUND(SUM(plan_max_val_dense_rank_dense_rank) / NULLIF(COUNT(CASE WHEN plan = 'basic' THEN 1 END), 0), 2) AS plan_max_val_dense_rank_dense_rank_per_basic, COUNT(*) AS event_count, SUM(CASE WHEN plan = 'starter' THEN plan_count_val_dense_rank ELSE 0 END) AS starter_plan_count_val_dense_rank, APPROX_PERCENTILE(plan_max_val_dense_rank_share, ARRAY(0.25, 0.5, 0.75)) AS plan_max_val_dense_rank_share_quartiles, SUM(plan_max_val_dense_rank_dense_rank) FILTER (WHERE plan = 'starter') AS starter_total_plan_max_val_dense_rank_dense_rank, AVG(plan_max_val_dense_rank) FILTER (WHERE plan = 'basic') AS basic_avg_plan_max_val_dense_rank FROM valid_price_tiers GROUP BY 1 HAVING starter_total_plan_max_val_dense_rank_dense_rank < 1000000 ORDER BY starter_plan_count_val_dense_rank DESC NULLS LAST;
